<?php

namespace App\Services;

use Illuminate\Http\Request;
use Illuminate\Support\Facades\Log;

class BotProtectionService
{
    /**
     * Check if the incoming request is generated by a bot or automated scanner.
     */
    public static function isSuspicious(Request $request): bool
    {
        // 1. Honeypot check: If the hidden honeypot field has any value, it is a bot
        if (!empty($request->input('website_url')) || !empty($request->input('company_fax')) || !empty($request->input('honey_token'))) {
            Log::warning("Bot Protection: Honeypot triggered from IP: {$request->ip()} - User Agent: {$request->userAgent()}");
            return true;
        }

        // 2. Vulnerability Scanner / Command Injection Payload Check
        $suspiciousPatterns = [
            'bxss.me',
            'burpcollaborator',
            'interact.sh',
            'oastify.com',
            'oast.live',
            'oast.site',
            'oast.online',
            'nslookup',
            '$(nslookup',
            'curl hit',
            'wget hit',
            ';cat /etc/passwd',
            '|echo ',
            '|dir',
            'powershell',
            'etc/shadow',
            'phpinfo()',
            '<script>',
            'javascript:',
            'UNION SELECT',
            'CONCAT(',
            'WAITFOR DELAY',
            'SLEEP(',
        ];

        $allInputs = json_encode($request->all());

        foreach ($suspiciousPatterns as $pattern) {
            if (stripos($allInputs, $pattern) !== false) {
                Log::warning("Bot Protection: Scanner payload '{$pattern}' blocked from IP: {$request->ip()} - User Agent: {$request->userAgent()}");
                return true;
            }
        }

        return false;
    }
}
